sp_widget.client_script:
function loginCtrl($scope, $http, $window, $location, spUtil) {
  var c = this;
  c.loading = false;
  c.message = '';

  c.focusPassword = function() {
    var el = document.getElementById('password');
    if (el) el.focus();
  };

  c.login = function(username, password) {
    if (!username || !password) {
      c.message = 'Please enter your username and password.';
      return;
    }

    c.loading = true;
    c.message = '';
    var url = spUtil.getURL({ sysparm_type: 'view_form.login' });

    return $http({
      method: 'post',
      url: url,
      data: $.param({
        'sysparm_type': 'login',
        'user_name': username,
        'user_password': password,
        'remember_me': false,
        'get_redirect_url': true,
        'is_direct_redirect': true
      }),
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
    }).then(function(response) {
      c.loading = false;
      if (!response.data) {
        c.message = 'There was an error processing your request.';
        return;
      }
      if (response.data.status === 'success') {
        $window.location = response.data.redirect_url;
      } else if (response.data.status === 'mfa_code_required') {
        $window.location = '/validate_multifactor_auth_code.do';
      } else {
        c.message = response.data.message || 'Invalid username or password.';
        c.password = '';
        c.username = '';
        var el = document.getElementById('username');
        if (el) el.focus();
      }
    }, function() {
      c.loading = false;
      c.message = 'There was an error processing your request.';
    });
  };

  c.externalLogin = function() {
    $window.location = '/login_with_sso.do';
  };
}

sp_widget.css:
* {
  box-sizing: border-box;
}

.clm-login-viewport {
  position: relative;
  width: 100%;
  min-height: 100vh;
  margin: 0;
  padding: 40px 60px;
  background-color: #f7f9fa;
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Background Artwork */
.clm-bg-art {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.clm-bg-art svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* Container: reduced gap between left info and right card */
.clm-login-container {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 1180px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 36px; /* Reduced gap between columns */
}

/* ================= LEFT COLUMN ================= */
.clm-info-section {
  flex: 1.15;
  max-width: 580px;
  display: flex;
  flex-direction: column;
}

.clm-brand-header {
  margin-bottom: 20px; /* Reduced spacing */
}

/* Logo Integration */
.clm-logo-wrap {
  display: inline-block;
  background: transparent !important;
}

.clm-brand-logo {
  max-width: 220px;
  height: auto;
  display: block;
  background: transparent !important;
  mix-blend-mode: multiply;
}

.clm-brand-divider {
  width: 44px;
  height: 4px;
  background-color: #ffd800;
  border-radius: 2px;
  margin-bottom: 16px; /* Reduced spacing */
}

/* Strict Hierarchy:
   1. "Enable" (clm-headline) -> Boldest (900)
   2. "Credit Limit" (clm-kicker) -> Lower boldness (700)
   3. "Streamline" (clm-subtext) -> Lower boldness (500)
*/
.clm-headline {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 40px;
  font-weight: 900 !important; /* Boldest */
  line-height: 1.18;
  color: #000000 !important;
  margin: 0 0 12px; /* Reduced spacing */
  letter-spacing: -0.02em;
}

.clm-kicker {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 13px;
  font-weight: 700; /* Lower than headline */
  color: #334155;
  letter-spacing: 0.05em;
  word-spacing: 0.15em;
  margin-bottom: 8px; /* Reduced spacing */
  text-transform: uppercase;
}

.clm-subtext {
  font-family: 'Inter', sans-serif;
  font-size: 15.5px;
  font-weight: 500; /* Lower than kicker */
  line-height: 1.55;
  color: #556274;
  max-width: 480px;
  margin: 0 0 28px; /* Reduced spacing */
  letter-spacing: 0.005em;
}

/* Feature Columns */
.clm-features-row {
  display: inline-flex;
  align-items: center;
  margin-bottom: 32px; /* Reduced spacing */
}

.clm-feature-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0 22px;
}

.clm-feature-col:first-child {
  padding-left: 0;
}

.clm-feature-col:last-child {
  padding-right: 0;
}

/* Increased SVG Icon Size */
.clm-feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0f172a;
  margin-bottom: 8px;
}

.clm-feature-icon svg {
  width: 42px !important;
  height: 42px !important;
  display: block;
}

.clm-feature-label {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 13.5px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: 0.01em;
}

.clm-feature-sep {
  width: 1px;
  height: 42px;
  background-color: #cbd5e1;
}

/* Copyright text */
.clm-copyright-desktop {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 400;
  color: #94a3b8;
}

.clm-copyright-mobile {
  display: none;
}

/* ================= RIGHT CARD ================= */
.clm-card-section {
  flex: 0.85;
  display: flex;
  flex-direction: column;
  align-self: center !important; /* Self-align center */
  align-items: center;
}

.clm-card {
  width: 100%;
  max-width: 390px;
  background: #ffffff;
  border-radius: 16px;
  padding: 32px 28px; /* Reduced internal padding */
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.06);
}

.clm-card-header {
  margin-bottom: 18px; /* Reduced spacing */
}

.clm-card-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 4px;
  letter-spacing: -0.01em;
}

.clm-card-subtitle {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  font-weight: 400;
  color: #64748b;
  margin: 0;
}

/* Error Banner */
.clm-err {
  background: #fef2f2;
  border: 1px solid #f87171;
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 500;
  color: #b91c1c;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Inputs */
.clm-field {
  margin-bottom: 12px; /* Reduced spacing between inputs */
}

.clm-inp-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.clm-inp-icon {
  position: absolute;
  left: 14px;
  color: #64748b;
  display: flex;
  align-items: center;
  pointer-events: none;
}

.clm-inp {
  width: 100%;
  height: 44px;
  background: #f1f5f9;
  border: 1.5px solid transparent;
  border-radius: 8px;
  padding: 0 16px;
  font-size: 13.5px;
  font-weight: 400;
  color: #0f172a;
  outline: none;
  font-family: 'Inter', sans-serif;
  transition: all 0.16s ease;
}

.clm-inp-has-icon {
  padding-left: 44px;
}

.clm-inp:focus {
  background: #ffffff;
  border-color: #ffd800;
  box-shadow: 0 0 0 3px rgba(254, 216, 0, 0.28);
}

.clm-inp::placeholder {
  color: #94a3b8;
  font-weight: 400;
}

/* Action Button */
.clm-btn {
  width: 100%;
  height: 44px;
  background: #fedb00;
  border: none;
  border-radius: 8px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  margin-top: 8px; /* Reduced spacing */
  transition: background 0.15s ease, transform 0.1s ease;
}

.clm-btn:hover {
  background: #f2cb00;
  transform: translateY(-1px);
}

.clm-btn:active {
  transform: translateY(0);
}

.clm-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Divider */
.clm-separator {
  position: relative;
  text-align: center;
  margin: 14px 0; /* Reduced spacing */
}

.clm-separator::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  background: #e2e8f0;
}

.clm-separator span {
  position: relative;
  background: #ffffff;
  padding: 0 10px;
  font-size: 11px;
  font-weight: 500;
  color: #94a3b8;
  letter-spacing: 0.05em;
}

/* SSO Button */
.clm-sso-btn {
  width: 100%;
  height: 44px;
  background: #ffffff;
  border: 1.5px solid #0f172a;
  border-radius: 8px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  cursor: pointer;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.clm-sso-btn:hover {
  background: #f8fafc;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

/* Support Help */
.clm-help-link {
  margin-top: 16px; /* Reduced spacing */
  text-align: center;
  font-size: 12px;
  font-weight: 400;
  color: #64748b;
}

.clm-help-link a {
  color: #0265c2;
  font-weight: 600;
  text-decoration: none;
}

.clm-help-link a:hover {
  text-decoration: underline;
}

/* ================= RESPONSIVE ================= */
@media (max-width: 992px) {
  .clm-login-viewport {
    padding: 28px 20px;
  }

  .clm-login-container {
    flex-direction: column;
    align-items: center;
    gap: 28px;
  }

  .clm-info-section {
    max-width: 100%;
    text-align: center;
    align-items: center;
  }

  .clm-headline {
    font-size: 32px;
  }

  .clm-brand-divider {
    margin: 0 auto 12px auto;
  }

  .clm-features-row {
    justify-content: center;
  }

  .clm-card-section {
    align-items: center;
    width: 100%;
  }

  .clm-copyright-desktop {
    display: none;
  }

  .clm-copyright-mobile {
    display: block;
    font-size: 11px;
    font-weight: 400;
    color: #94a3b8;
    margin-top: 18px;
    text-align: center;
  }
}

@media (max-width: 520px) {
  .clm-features-row {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .clm-feature-sep {
    display: none;
  }

  .clm-feature-col {
    padding: 0;
  }

  .clm-card {
    padding: 22px 16px;
  }
}
